mapper.select:
SELECT  FROM dispatch_runtime_event
WHERE tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

SELECT  FROM dispatch_runtime_event e
WHERE e.tenant_id = #{tenantId} AND e.workitem_id = #{workitemId}
  AND EXISTS (
      SELECT 1 FROM dispatch d
      WHERE d.id = e.dispatch_id
        AND d.tenant_id = #{tenantId}
        AND d.source_type = 'WORKITEM'
        AND d.workitem_id = #{workitemId}
        AND d.is_deleted = 0
  )
ORDER BY id ASC

SELECT  FROM dispatch_runtime_event e
WHERE e.tenant_id = #{tenantId} AND e.workitem_id = #{workitemId}
  AND EXISTS (
      SELECT 1 FROM dispatch d
      WHERE d.id = e.dispatch_id
        AND d.tenant_id = #{tenantId}
        AND d.workitem_id = #{workitemId}
        AND d.is_deleted = 0
  )
ORDER BY id ASC

        SELECT  FROM dispatch_runtime_event
        WHERE tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
		ORDER BY COALESCE(seq, id) ASC, id ASC

SELECT  FROM dispatch_runtime_event
WHERE tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
ORDER BY id ASC

SELECT MAX(id) FROM dispatch_runtime_event
WHERE tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
  AND event_type <> 'agent.message'

SELECT  FROM dispatch_runtime_event
WHERE tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
  AND id > #{afterId}
ORDER BY id ASC

SELECT  FROM dispatch_runtime_event
WHERE tenant_id = #{tenantId}
  AND dispatch_id = #{dispatchId}
  AND event_type = #{eventType}
ORDER BY id DESC
LIMIT 1
